import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import test from 'node:test';
import { ed25519KeypairFromSeed } from '@ifay/sdk';
import {
  BUF_HEADER_SIZE,
  crc32Ieee,
  decodeCanonicalCbor,
  encodeCanonicalCbor,
  packBufBinary,
  parseBufBinary,
} from '../src/index.mjs';

// Golden 522-byte BUF\0 v1 artifact generated by Rust `fayger pack --entry main --section soul_profile:data=<"hello-soul">`
const RUST_FAYGER_PACK_GOLDEN_HEX =
  '42554600010000002800000000000000f1000000000000001901000000000000bb00000000000000' +
  'a465656e747279646d61696e6873656374696f6e7381a66269646c736f756c5f70726f66696c65' +
  '646b696e64646461746166646967657374a26576616c75659820186118ed1893189d186a1864182e' +
  '18d518ba1839187b1826187918d5010a18fb18511118b518a9183f18b61874185e1899181b187e' +
  '183f184218d218b369616c676f726974686d66736861323536666c656e6774680a6a766973696269' +
  '6c6974796872657175697265647370726f66696c655f636f6e73747261696e7473a06e736368656d' +
  '615f76657273696f6e65312e302e307572756e74696d655f696e746572666163655f6d696e65312e' +
  '302e3081a7646b696e64646461746166646967657374a26576616c75659820186118ed1893189d' +
  '186a1864182e18d518ba1839187b1826187918d5010a18fb18511118b518a9183f18b61874185e' +
  '1899181b187e183f184218d218b369616c676f726974686d66736861323536666c656e6774680a' +
  '666f6666736574006a73656374696f6e5f69646c736f756c5f70726f66696c656a7669736962696c' +
  '6974796872657175697265647370726f66696c655f636f6e73747261696e7473a068656c6c6f2d73' +
  '6f756c0a02000000000000c0d5aa6adad4bfb358e705c73175d7e46fc61cf4c56140c78e98487cbd' +
  'f3aa8726bcab8e';

const SIBLING_FAYGER_BIN = resolve(
  import.meta.dirname,
  '../../../../fayger/release/dev/core/target/debug/fayger',
);

test('IEEE CRC-32 and RFC 8949 canonical CBOR match FayGer reference vectors', () => {
  assert.equal(crc32Ieee(''), 0);
  assert.equal(crc32Ieee('123456789'), 0xcbf43926);

  assert.equal(encodeCanonicalCbor(0).toString('hex'), '00');
  assert.equal(encodeCanonicalCbor(23).toString('hex'), '17');
  assert.equal(encodeCanonicalCbor(24).toString('hex'), '1818');
  assert.equal(encodeCanonicalCbor(255).toString('hex'), '18ff');
  assert.equal(encodeCanonicalCbor(256).toString('hex'), '190100');
  assert.equal(encodeCanonicalCbor(1000000).toString('hex'), '1a000f4240');
  assert.equal(encodeCanonicalCbor(-1).toString('hex'), '20');
  assert.equal(encodeCanonicalCbor(-100).toString('hex'), '3863');

  // Map keys must be sorted by encoded CBOR key bytes (shorter length before longer)
  const encodedMap = encodeCanonicalCbor({ runtime_interface_min: '1.0.0', entry: 'main' });
  const decodedMap = decodeCanonicalCbor(encodedMap);
  assert.deepEqual(decodedMap, { entry: 'main', runtime_interface_min: '1.0.0' });
  // 'entry' (len 5 -> 0x65) sorts before 'runtime_interface_min' (len 21 -> 0x75)
  assert.equal(encodedMap[0], 0xa2);
  assert.equal(encodedMap[1], 0x65);

  // Reject floats, non-shortest ints, unsorted map keys, and indefinite lengths
  assert.throws(() => encodeCanonicalCbor(1.5), /floating-point/);
  assert.throws(() => decodeCanonicalCbor(Buffer.from([0x19, 0x00, 0x18])), /IntegerNotShortest/);
  assert.throws(
    () => decodeCanonicalCbor(Buffer.from([0xa2, 0x61, 0x7a, 0x02, 0x61, 0x61, 0x01])),
    /MapKeysNotSorted/,
  );
  assert.throws(() => decodeCanonicalCbor(Buffer.from([0x9f, 0x01, 0xff])), /IndefiniteLength/);
});

test('packBufBinary produces exact bit-for-bit match with Rust fayger pack golden vector', () => {
  const packed = packBufBinary({
    schemaVersion: '1.0.0',
    runtimeInterfaceMin: '1.0.0',
    entry: 'main',
    sections: [
      {
        id: 'soul_profile',
        kind: 'data',
        visibility: 'required',
        payload: 'hello-soul',
      },
    ],
  });

  assert.equal(packed.length, 522);
  assert.equal(packed.toString('hex'), RUST_FAYGER_PACK_GOLDEN_HEX);

  const parsed = parseBufBinary(packed);
  assert.equal(parsed.header.magic, 'BUF\\0');
  assert.equal(parsed.header.formatVersion, 1);
  assert.equal(parsed.manifest.entry, 'main');
  assert.equal(parsed.sections.length, 1);
  assert.equal(parsed.sections[0].payload.toString('utf8'), 'hello-soul');
  assert.equal(parsed.verified.digestValid, true);
  assert.equal(parsed.verified.crc32Valid, true);
});

test('packBufBinary seal_and_sign and tamper detection catch manifest, payload, CRC32, and sig corruption', () => {
  const seed = Buffer.alloc(32, 0x09);
  const kp = ed25519KeypairFromSeed(seed);

  const signedBuf = packBufBinary({
    entry: 'main',
    capabilities: ['fs.read', 'crypto.hash'],
    quotas: { cpu_ms_per_sec: 300, memory_bytes: 67108864 },
    extensions: { fay_entity_kind: 'ifay', custom_epoch: 42 },
    sections: [
      { id: 'code', kind: 'code', payload: '{"op":"noop"}' },
      { id: 'data', kind: 'data', visibility: 'optional', payload: 'payload-bytes' },
    ],
    signer: {
      seed32: seed,
      publicKeyRef: 'k-soul-test',
    },
  });

  const verified = parseBufBinary(signedBuf, {
    trustedPublicKeyHex: kp.publicKeyHex,
    requireSignatureVerification: true,
  });
  assert.equal(verified.verified.signatureStatus, 'valid');
  assert.equal(verified.manifest.extensions.fay_entity_kind, 'ifay');
  assert.equal(verified.manifest.extensions.custom_epoch, 42);

  // Wrong public key fails signature verification
  const wrongKp = ed25519KeypairFromSeed(Buffer.alloc(32, 0x07));
  assert.throws(
    () =>
      parseBufBinary(signedBuf, {
        trustedPublicKeyHex: wrongKp.publicKeyHex,
        requireSignatureVerification: true,
      }),
    /LDR_SIGNATURE_FAIL \[InvalidSignature\]/,
  );

  // Flip 1 bit in manifest region -> ManifestDigest or CBOR failure
  const badManifest = Buffer.from(signedBuf);
  badManifest[BUF_HEADER_SIZE + 2] ^= 0x01;
  assert.throws(() => parseBufBinary(badManifest), /LDR_PARSE_FAIL|LDR_DIGEST_MISMATCH/);

  // Flip 1 bit in last section payload -> SectionDigest mismatch
  const badPayload = Buffer.from(signedBuf);
  badPayload[badPayload.length - 45] ^= 0xff;
  assert.throws(() => parseBufBinary(badPayload), /LDR_DIGEST_MISMATCH \[SectionDigest\]/);

  // Flip 1 bit in trailer CRC32 -> Crc32 mismatch
  const badCrc = Buffer.from(signedBuf);
  badCrc[badCrc.length - 1] ^= 0xff;
  assert.throws(() => parseBufBinary(badCrc), /LDR_DIGEST_MISMATCH \[Crc32\]/);
});

test('cross-language interoperability with sibling Rust fayger inspect & run when available', () => {
  if (!existsSync(SIBLING_FAYGER_BIN)) {
    return;
  }
  const tmp = mkdtempSync(join(tmpdir(), 'ifay-soul-rust-interop-'));
  try {
    const seed = Buffer.alloc(32, 0x15);
    const bufBytes = packBufBinary({
      entry: 'main',
      capabilities: ['fs.read', 'crypto.hash'],
      quotas: { cpu_ms_per_sec: 400, memory_bytes: 134217728 },
      extensions: { fay_entity_kind: 'ifay' },
      sections: [
        { id: 'code', kind: 'code', payload: '{"schema_version":"fayger-task-ir/1.0","steps":[]}' },
        { id: 'soul_profile', kind: 'data', payload: '{"hello":"fayger"}' },
      ],
      signer: {
        seed32: seed,
        publicKeyRef: 'ifay_interop#k1',
      },
    });

    const bufPath = join(tmp, 'js-produced.buf');
    writeFileSync(bufPath, bufBytes);

    const inspectOut = execFileSync(SIBLING_FAYGER_BIN, ['inspect', bufPath], {
      encoding: 'utf8',
    });
    assert.match(inspectOut, /schema_version:\s+1\.0\.0/);
    assert.match(inspectOut, /soul_profile \[data\]/);
    assert.match(inspectOut, /signature:\s+present/);

    const runOut = execFileSync(SIBLING_FAYGER_BIN, ['run', bufPath], {
      encoding: 'utf8',
    });
    assert.match(runOut, /final_state:\s+Terminated/);
    assert.match(runOut, /dispatched:\s+2/);

    // Reverse direction: Rust `fayger pack` -> JS `parseBufBinary`
    const payloadFile = join(tmp, 'rust-sec.bin');
    const rustBufPath = join(tmp, 'rust-produced.buf');
    writeFileSync(payloadFile, 'from-rust-fayger');
    execFileSync(
      SIBLING_FAYGER_BIN,
      ['pack', '--entry', 'main', '--section', `sec_a:data=${payloadFile}`, '-o', rustBufPath],
      { encoding: 'utf8' },
    );
    const parsedFromRust = parseBufBinary(readFileSync(rustBufPath));
    assert.equal(parsedFromRust.sections[0].id, 'sec_a');
    assert.equal(parsedFromRust.sections[0].payload.toString('utf8'), 'from-rust-fayger');
    assert.equal(parsedFromRust.verified.digestValid, true);
    assert.equal(parsedFromRust.verified.crc32Valid, true);
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
});
